  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `bill_city` varchar(30) DEFAULT NULL,
  `bill_code` varchar(30) DEFAULT NULL,
  `bill_country` varchar(30) DEFAULT NULL,
  `bill_state` varchar(30) DEFAULT NULL,
  `bill_street` varchar(250) DEFAULT NULL,
  `servicecasher` int(11) DEFAULT '0',
  `servicegroup` int(11) DEFAULT '0',
  `traffic` varchar(100) DEFAULT NULL,
  `completed` varchar(25) DEFAULT NULL,
  `totalintegral` int(11) DEFAULT '0',
  `consumedintegral` int(11) DEFAULT '0',
  `expiredintegral` int(11) DEFAULT '0',
  `availableintegral` int(11) DEFAULT '0',
  `lastservicedate` date DEFAULT NULL,
  `distributiondate` date DEFAULT NULL,
  `potentialid` int(11) DEFAULT '0',
  `lastcontactuser` int(19) DEFAULT '0',
  `nolinkdays` int(19) DEFAULT NULL,
  `longtitude` varchar(200) DEFAULT NULL,
  `latitude` varchar(200) DEFAULT NULL,
  `location_address` varchar(200) DEFAULT NULL,
  `qualifymaturitydate` date DEFAULT NULL,
  `firt_concatuser` int(19) DEFAULT '0',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `productcategory` varchar(200) DEFAULT NULL,
  `promotionalpartner` int(11) DEFAULT '0',
  `promoter` int(11) DEFAULT '0',
  `print_times` int(11) DEFAULT '0',
  `bw_id` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  `bill_area` varchar(100) DEFAULT NULL,
  `locationaddress` varchar(255) DEFAULT NULL,
  `locationaddress_map` varchar(20) DEFAULT NULL,
  PRIMARY KEY (`accountid`),
  KEY `deleted` (`deleted`),
  KEY `publicaccount` (`publicaccount`),
  CONSTRAINT `ld_account_ibfk_1` FOREIGN KEY (`accountid`) REFERENCES `ld_crmentity` (`crmid`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

