  `salesorderid` int(11) NOT NULL COMMENT '合同订单ID',
  `smownerid` int(11) DEFAULT NULL COMMENT '负责人ID',
  `outdate` date DEFAULT NULL COMMENT '出库日期',
  `wareid` int(11) DEFAULT NULL COMMENT '仓库ID',
  `presence` varchar(50) DEFAULT '未出库',
  `remark` varchar(500) DEFAULT NULL,
  `taxtype` varchar(25) DEFAULT NULL COMMENT '税的类型',
  `currency_id` int(11) DEFAULT NULL COMMENT '币种',
  `total` decimal(25,6) DEFAULT NULL,
  `subtotal` decimal(25,6) DEFAULT NULL,
  `conversion_rate` decimal(25,6) DEFAULT NULL,
  `currency_symbol` varchar(30) DEFAULT NULL,
  `adjustment` decimal(25,6) DEFAULT NULL,
  `s_h_amount` decimal(25,2) DEFAULT NULL,
  `discount_amount` decimal(25,6) DEFAULT NULL,
  `discount_percent` decimal(25,2) DEFAULT NULL,
  `subsmownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `contactid` int(11) DEFAULT '0',
  `discount_type` int(1) DEFAULT '0',
  `receivable_balance` decimal(20,2) DEFAULT '0.00',
  `received_amount` decimal(20,2) DEFAULT '0.00',
  `cashbilldate` date DEFAULT NULL,
  `have_invoicetotal` decimal(20,2) DEFAULT '0.00',
  `nothave_invoicetotal` decimal(20,2) DEFAULT '0.00',
  `lastinvoicedate` date DEFAULT NULL,
  `lastinvoice_no` varchar(200) DEFAULT NULL,
  `approveby` int(19) DEFAULT '0',
  `approvestatus` varchar(200) DEFAULT '未提交',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `print_times` int(11) DEFAULT '0',
  `express_company` varchar(255) DEFAULT NULL,
  `express_no` text,
  `approvetime` datetime DEFAULT NULL,
  PRIMARY KEY (`out_id`),
  KEY `outboundorder_presence` (`presence`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

