  `discount_percent` decimal(25,2) DEFAULT NULL,
  `subsmownerid` int(11) DEFAULT '0',
  `smcreatorid` int(11) DEFAULT '0',
  `modifiedby` int(11) DEFAULT '0',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `description` text,
  `deleted` int(11) DEFAULT '0',
  `contactid` int(11) DEFAULT '0',
  `discount_type` int(1) DEFAULT '0',
  `pay_balance` decimal(25,2) DEFAULT '0.00',
  `pay_amount` decimal(25,2) DEFAULT '0.00',
  `sendcashbilldate` date DEFAULT NULL,
  `stockpresence` varchar(50) DEFAULT NULL,
  `have_invoicetotal` decimal(20,2) DEFAULT '0.00',
  `lastinvoicedate` date DEFAULT NULL,
  `nothave_invoicetotal` decimal(20,2) DEFAULT '0.00',
  `lastinvoice_no` varchar(200) DEFAULT NULL,
  `approveby` int(19) DEFAULT '0',
  `approvestatus` varchar(200) DEFAULT '未提交',
  `currentapprover` varchar(1000) DEFAULT NULL,
  `vendorid` int(11) DEFAULT '0',
  `print_times` int(11) DEFAULT '0',
  `approvetime` datetime DEFAULT NULL,
  PRIMARY KEY (`stock_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8;

