  `holidays` varchar(60) DEFAULT NULL,
  `namedays` varchar(60) DEFAULT NULL,
  `workdays` varchar(30) DEFAULT NULL,
  `weekstart` int(11) DEFAULT NULL,
  `date_format` varchar(200) DEFAULT NULL,
  `hour_format` varchar(30) DEFAULT 'am/pm',
  `start_hour` varchar(30) DEFAULT '10:00',
  `end_hour` varchar(30) DEFAULT '23:00',
  `activity_view` varchar(200) DEFAULT 'Today',
  `lead_view` varchar(200) DEFAULT 'Today',
  `imagename` varchar(250) DEFAULT NULL,
  `deleted` int(1) NOT NULL DEFAULT '0',
  `confirm_password` varchar(300) DEFAULT NULL,
  `internal_mailer` varchar(3) NOT NULL DEFAULT '1',
  `reminder_interval` varchar(100) DEFAULT NULL,
  `reminder_next_time` varchar(100) DEFAULT NULL,
  `crypt_type` varchar(20) NOT NULL DEFAULT 'MD5',
  `accesskey` varchar(36) DEFAULT NULL,
  `theme` varchar(100) DEFAULT NULL,
  `language` varchar(36) DEFAULT NULL,
  `time_zone` varchar(200) DEFAULT NULL,
  `currency_grouping_pattern` varchar(100) DEFAULT NULL,
  `currency_decimal_separator` varchar(2) DEFAULT NULL,
  `currency_grouping_separator` varchar(2) DEFAULT NULL,
  `currency_symbol_placement` varchar(20) DEFAULT NULL,
  `level` int(11) DEFAULT NULL,
  `approvestatus` int(1) DEFAULT NULL,
  `approveby` int(19) DEFAULT NULL,
  `accountallview` int(11) DEFAULT '0',
  `select_servicedetail` int(11) DEFAULT '0',
  `select_due_date` int(11) DEFAULT '0',
  `login_sms` int(11) DEFAULT '0',
  `menuapproval` int(1) DEFAULT '0',
  `reader` int(11) DEFAULT '0',
  `profileid` int(11) DEFAULT '0',
  `scopeauthority` int(1) DEFAULT '0',
  `viewothers` int(1) DEFAULT '0',
  `editothers` int(1) DEFAULT '0',
  `delothers` int(1) DEFAULT '0',
  `viewselfbills` int(1) DEFAULT '0',
  `userlevel` varchar(200) DEFAULT NULL,
  `dailyreporttemplet` text,
  `weekreporttemplet` text,
  `monthtypetemplet` text,
  `dingjie_permit` int(11) DEFAULT '0',
  `telephone_view` int(10) DEFAULT NULL,
  `edit_other_mobile` int(4) DEFAULT '0',
  `push_work_reminds` int(4) DEFAULT '1',
  `push_news_reminds` int(4) DEFAULT '1',
  `groupid` varchar(100) DEFAULT NULL,
  `is_mobile_style` int(2) DEFAULT '1',
  `trackgroupid` int(11) DEFAULT '0',
  `bangwo8_supportname` varchar(50) DEFAULT NULL,
  `jw_user` varchar(25) DEFAULT NULL,
  `sopho_exten` varchar(25) DEFAULT NULL,
  `sopho_queue` varchar(25) DEFAULT NULL,
  `wx_userid` varchar(255) DEFAULT NULL,
  `edit_me_mobile` int(10) DEFAULT '1',
  `hantian_exten` varchar(25) DEFAULT NULL,
  `hire_date` date DEFAULT NULL,
  `push_wx_reminds` int(4) DEFAULT '1',
  `createdtime` datetime DEFAULT NULL,
  `modifiedtime` datetime DEFAULT NULL,
  `modifiedby` int(19) DEFAULT '0',
  `smcreatorid` int(19) DEFAULT '0',
  `wxviewedmodules` varchar(255) DEFAULT NULL,
  `usercolor` varchar(50) DEFAULT NULL,
  `campaignsview` int(11) DEFAULT '0',
  `wx_userid_old` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `user_user_name_idx` (`user_name`) USING BTREE,
  KEY `user_user_password_idx` (`user_password`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8;

