	END IF;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for addtabintoprofile
-- ----------------------------
DROP PROCEDURE IF EXISTS `addtabintoprofile`;
DELIMITER ;;
CREATE PROCEDURE `addtabintoprofile`(
tabname varchar(50),
permissions int(19)

)
begin
	declare done  int  default 0;
	declare pprofileid  int ;
	declare cur1 CURSOR FOR SELECT profileid  FROM  ld_profile;
	declare continue handler  for not   found  SET done =1;
	set @sql =concat('select tabid into @tabid from ld_tab where name=','''',tabname,'''');
	prepare stmt from @sql;
	execute stmt;
	deallocate  prepare stmt;
	OPEN cur1;
	Fetch cur1 into pprofileid;
	 loop1: while  done<>1 DO
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',0,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=0)' );
				  prepare stmt from @sql;
			 execute stmt;
	deallocate prepare stmt;
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',1,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=1)' );
				  prepare stmt from @sql;
			 execute stmt;
	deallocate prepare stmt;
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',2,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=2)' );
				  prepare stmt from @sql;
			 execute stmt;
	deallocate prepare stmt;
	set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',3,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=3)' );
	prepare stmt from @sql;
			 execute stmt;
	deallocate prepare stmt;
			  set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',4,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=4)' );
				  prepare stmt from @sql;
			 execute stmt;
	deallocate prepare stmt;
		 set @sql=CONCAT('insert into ld_profile2standardpermissions(profileid,tabid,operation,permissions) select  ' ,pprofileid,',',@tabid,',',11,',',permissions,'  from dual  where not exists (select 1 from ld_profile2standardpermissions where profileid=',pprofileid, ' and  tabid=',@tabid,' and operation=11)' );
				  prepare stmt from @sql;
			 execute stmt;
	deallocate prepare stmt;
	Fetch cur1 into pprofileid;
	end while loop1;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for addtableIndex
-- ----------------------------
DROP PROCEDURE IF EXISTS `addtableIndex`;
DELIMITER ;;
CREATE PROCEDURE `addtableIndex`(
	tablename 	varchar(50),
	indexname 	varchar(50),
	columnlist 	varchar(50)
)
begin
	
	SELECT DATABASE() into @datebase;

	SET @sql2=CONCAT('select count(*) into @cnt from information_schema.statistics where table_name=''',tablename,''' and index_name=''',indexname,'''  and table_schema=''',@datebase,'''');  
	PREPARE statement_name FROM @sql2;  
	EXECUTE statement_name; 
	DEALLOCATE PREPARE statement_name;

	IF @cnt=0 THEN 
		SET @sql3=CONCAT('alter  table ',tablename,' add  index ',indexname,' (',columnlist,')' );
		PREPARE statement_name FROM @sql3;  
		EXECUTE statement_name; 
		DEALLOCATE PREPARE statement_name;
  END IF;
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for addTranLabel
-- ----------------------------
DROP PROCEDURE IF EXISTS `addTranLabel`;
DELIMITER ;;
CREATE PROCEDURE `addTranLabel`(IN tab_id int,IN fieldid int,IN tablename VARCHAR(100),IN var_labelbol VARCHAR(100),IN producttoofield int)
begin
	if(var_labelbol != '')
	THEN
		if(var_labelbol = 'DISCOUNT')
		THEN	
			set @fieldlabel = '折扣(%)';
		else
			select fieldlabel into @fieldlabel from ld_desk where labelbol = var_labelbol and languagetype = 'zh' and Labeltype = 'fixedstr';
		end if;
		select fieldlabel into @fieldlabel from ld_desk where labelbol = var_labelbol and languagetype = 'en' and Labeltype = 'fixedstr';
	ELSE
		select fieldlabel into @fieldlabel from ld_tranlabel where tabid = tab_id and Relateid = fieldid and trantable = 'ld_field' and languagetype = 'zh';
		select fieldlabel into @fieldlabel from ld_tranlabel where tabid = tab_id and Relateid = fieldid and trantable = 'ld_field' and languagetype = 'en';
	END IF;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for altercolumn
-- ----------------------------
DROP PROCEDURE IF EXISTS `altercolumn`;
DELIMITER ;;
CREATE PROCEDURE `altercolumn`(
  tablename VARCHAR(50),
  oldcolumnname VARCHAR(100),
  newcolumnname VARCHAR(100),
  newcolumntype VARCHAR(100)
)
BEGIN
    SELECT DATABASE() INTO @tableschema;
    SET tablename=LOWER(tablename);
    SET @colName=0;

    select length(column_name) into @colName from information_schema.columns
    where TABLE_SCHEMA= @tableschema and table_name=tablename and COLUMN_NAME=oldcolumnname;

    IF @colName>0 THEN

      SET @altersql=CONCAT(' alter table ',tablename, ' change ',oldcolumnname,' ',newcolumnname,' ',newcolumntype);

      PREPARE stalter FROM @altersql;
      EXECUTE stalter;
    END IF;

  end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for altercolumnfor_primarykey
-- ----------------------------
DROP PROCEDURE IF EXISTS `altercolumnfor_primarykey`;
DELIMITER ;;
CREATE PROCEDURE `altercolumnfor_primarykey`(
 tablename varchar(50),
 columnname varchar(50)
)
BEGIN
    SELECT DATABASE() INTO @tableschema;
    SET tablename=LOWER(tablename);
    SET @primaryNum=0;
		select database() into @db_name;
		
		select count(*) into @primaryNum
		from INFORMATION_SCHEMA.KEY_COLUMN_USAGE t
		where t.table_schema = @db_name and t.TABLE_NAME = tablename and COLUMN_NAME = columnname;
		IF @primaryNum = 0 THEN
			
      SET @altersql=CONCAT(' alter table ',tablename, ' change ',columnname,' ',columnname,' int primary key auto_increment');
      PREPARE stalter FROM @altersql;
      EXECUTE stalter;

			set @altersql1 = CONCAT(' alter table ',tablename, ' change ',columnname,' ',columnname,' int NOT NULL auto_increment');
			PREPARE stalter FROM @altersql1;
      EXECUTE stalter;
			
    END IF;
 end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for CopyModuleBlocks
-- ----------------------------
DROP PROCEDURE IF EXISTS `CopyModuleBlocks`;
DELIMITER ;;
CREATE PROCEDURE `CopyModuleBlocks`(
	IN copymodule VARCHAR(100),
	IN tomodule VARCHAR(100)
)
BEGIN
	#Routine body goes here...
declare done  int  default 0;
DECLARE bl_blocklabel varchar (100);
DECLARE bl_sequence int;
DECLARE bl_visible int; 
DECLARE bl_create_view int;
DECLARE bl_edit_view int;
DECLARE bl_detail_view int;
DECLARE bl_display_status int;
DECLARE bl_iscustom int;

declare cur1 CURSOR FOR SELECT  blocklabel,sequence,visible,create_view,edit_view,detail_view,display_status,iscustom from ld_blocks where tabid = (select tabid from ld_tab where name = copymodule);
declare continue handler  for not   found  SET done =1;

select tabid into @tabid from ld_tab where `name` = tomodule;
select tabid into @accountid from ld_tab where `name` = copymodule;
select max(blockid) into @blockid from ld_blocks;

OPEN cur1;
Fetch cur1 into bl_blocklabel,bl_sequence,bl_visible,bl_create_view,bl_edit_view,bl_detail_view,bl_display_status,bl_iscustom;
 loop1: while  done<>1 DO
	set @blockid = @blockid +1;
	-- 插入ld_field
	select @blockid,@tabid,bl_blocklabel,bl_sequence,bl_visible,bl_create_view,bl_edit_view,bl_detail_view,bl_display_status,bl_iscustom 
	from dual  where not exists(select 1 from ld_blocks where tabid=@tabid and blocklabel = bl_blocklabel);

	-- 获取blockid
	select blockid into @isblockid from ld_blocks where tabid = @accountid and blocklabel = bl_blocklabel;
	
	-- 中文插入
	select ld_tranlabel.fieldlabel into @fieldlabel from ld_tranlabel where tabid = @accountid and Relateid = @isblockid and trantable = 'ld_blocks' and languagetype = 'zh';
	select 'zh','ld_blocks',@tabid,@blockid,@fieldlabel from dual where not exists(select 1 from ld_tranlabel where tabid = @tabid and Relateid = @blockid and languagetype = 'zh');

	-- 英文插入
	select ld_tranlabel.fieldlabel into @fieldlabel from ld_tranlabel where tabid = @accountid and Relateid = @isblockid and trantable = 'ld_blocks' and languagetype = 'en';
	select 'en','ld_blocks',@tabid,@blockid,@fieldlabel from dual where not exists(select 1 from ld_tranlabel where tabid = @tabid and Relateid = @blockid and languagetype = 'en');
	
Fetch cur1 into bl_blocklabel,bl_sequence,bl_visible,bl_create_view,bl_edit_view,bl_detail_view,bl_display_status,bl_iscustom;
end while loop1;
close cur1;

update ld_blocks_seq set id = (select max(blockid) from ld_blocks);

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for CopyModuleField
-- ----------------------------
DROP PROCEDURE IF EXISTS `CopyModuleField`;
DELIMITER ;;
CREATE PROCEDURE `CopyModuleField`(
	IN copymodule VARCHAR(100),
	IN tomodule VARCHAR(100)
)
BEGIN
	#Routine body goes here...
declare done  int  default 0;
declare is_columnname  varchar (30);
declare is_tablename varchar (50) ;
declare is_generatedtype int ;
declare is_uitype varchar (19);
declare is_fieldname varchar (50);
declare is_fieldlabel varchar (50) ;
declare is_readonly int;
declare is_presence int ;
declare is_defaultvalue text ;
declare is_maximumlength int;
declare is_sequence int;
declare is_block int;
declare is_displaytype int;
declare is_typeofdata varchar(100);
declare is_quickcreate int;
declare is_quickcreatesequence int;
declare is_info_type varchar (20);
declare is_masseditable int;
declare is_fieldonly int;
declare is_issmownerid int;
declare cur1 CURSOR FOR SELECT  columnname,tablename,generatedtype,uitype,fieldname,fieldlabel,readonly,presence,defaultvalue,maximumlength,sequence,block,
displaytype,typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,fieldonly,issmownerid from ld_field where tabid = (select tabid from ld_tab where name = copymodule) and presence in (0,2);
declare continue handler  for not   found  SET done =1;

select tabid into @tabid from ld_tab where `name` = tomodule;
select tabid into @accountid from ld_tab where `name` = copymodule;
select max(fieldid) into @fieldid from ld_field;

OPEN cur1;
Fetch cur1 into is_columnname,is_tablename,is_generatedtype,is_uitype,is_fieldname,is_fieldlabel,is_readonly,is_presence,is_defaultvalue,is_maximumlength,is_sequence,is_block,
is_displaytype,is_typeofdata,is_quickcreate,is_quickcreatesequence,is_info_type,is_masseditable,is_fieldonly,is_issmownerid;
 loop1: while  done<>1 DO
	set @fieldid = @fieldid +1;
	-- 插入ld_field
	select blockid into @newblockid from ld_blocks where blocklabel = (select blocklabel from ld_blocks where blockid = is_block) and tabid = @tabid;
	displaytype,typeofdata,quickcreate,quickcreatesequence,info_type,masseditable,fieldonly,issmownerid)
	select @tabid,@fieldid,is_columnname,is_tablename,is_generatedtype,is_uitype,is_fieldname,is_fieldlabel,is_readonly,is_presence,is_defaultvalue,is_maximumlength,is_sequence,@newblockid,
	is_displaytype,is_typeofdata,is_quickcreate,is_quickcreatesequence,is_info_type,is_masseditable,is_fieldonly,is_issmownerid from dual  where not exists(select 1 from ld_field where tabid=@tabid and columnname = is_columnname);
	-- 获取field
	select fieldid into @isfieldid from ld_field where tabid = @accountid and columnname = is_columnname;
	
	-- 中文插入
	select ld_tranlabel.fieldlabel into @fieldlabel from ld_tranlabel where tabid = @accountid and Relateid = @isfieldid and trantable = 'ld_field' and languagetype = 'zh';
	select 'zh','ld_field',@tabid,@fieldid,@fieldlabel from dual where not exists(select 1 from ld_tranlabel where tabid = @tabid and fieldlabel = @fieldlabel and languagetype = 'zh');

	-- 英文插入
	select ld_tranlabel.fieldlabel into @fieldlabel from ld_tranlabel where tabid = @accountid and Relateid = @isfieldid and ld_tranlabel.trantable = 'ld_field' and languagetype = 'en';
	select 'en','ld_field',@tabid,@fieldid,@fieldlabel from dual where not exists(select 1 from ld_tranlabel where tabid = @tabid and fieldlabel = @fieldlabel and languagetype = 'en');
 
Fetch cur1 into is_columnname,is_tablename,is_generatedtype,is_uitype,is_fieldname,is_fieldlabel,is_readonly,is_presence,is_defaultvalue,is_maximumlength,is_sequence,is_block,
is_displaytype,is_typeofdata,is_quickcreate,is_quickcreatesequence,is_info_type,is_masseditable,is_fieldonly,is_issmownerid;
end while loop1;
close cur1;

update ld_field_seq set id = (select max(fieldid) from ld_field);

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for CopyModuleQuickActions
-- ----------------------------
DROP PROCEDURE IF EXISTS `CopyModuleQuickActions`;
DELIMITER ;;
CREATE PROCEDURE `CopyModuleQuickActions`(
	IN copymodule VARCHAR(100),
	IN tomodule VARCHAR(100)
)
BEGIN
	#Routine body goes here...
declare done  int  default 0;
DECLARE qa_related_tabid int;
DECLARE qa_sequence int;
DECLARE qa_presence int; 
DECLARE qa_label varchar(100);
declare cur1 CURSOR FOR SELECT  related_tabid,sequence,presence,label from ld_quickactions where tabid = (select tabid from ld_tab where name = copymodule);
declare continue handler  for not   found  SET done =1;

select tabid into @tabid from ld_tab where `name` = tomodule;

OPEN cur1;
Fetch cur1 into qa_related_tabid,qa_sequence,qa_presence,qa_label;
 loop1: while  done<>1 DO
	-- 操作信息插入
	select @tabid,qa_related_tabid,qa_sequence,qa_presence,qa_label 
	from dual  where not exists(select 1 from ld_quickactions where tabid=@tabid and related_tabid = qa_related_tabid);

Fetch cur1 into qa_related_tabid,qa_sequence,qa_presence,qa_label;
end while loop1;
close cur1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for CopyModuleRelatedLists
-- ----------------------------
DROP PROCEDURE IF EXISTS `CopyModuleRelatedLists`;
DELIMITER ;;
CREATE PROCEDURE `CopyModuleRelatedLists`(
	IN copymodule VARCHAR(100),
	IN tomodule VARCHAR(100)
)
BEGIN
	#Routine body goes here...
declare done  int  default 0;
DECLARE rl_related_tabid int;
DECLARE rl_name varchar(100);
DECLARE rl_sequence int; 
DECLARE rl_label varchar(100);
DECLARE rl_presence int; 
DECLARE rl_actions varchar(100); 
declare cur1 CURSOR FOR SELECT  related_tabid,name,sequence,label,presence,actions from ld_relatedlists where tabid = (select tabid from ld_tab where name = copymodule);
declare continue handler  for not   found  SET done =1;

select tabid into @tabid from ld_tab where `name` = tomodule;
select max(relation_id) into @relation_id from ld_relatedlists;
OPEN cur1;
Fetch cur1 into rl_related_tabid,rl_name,rl_sequence,rl_label,rl_presence,rl_actions;
 loop1: while  done<>1 DO
	-- 相关信息插入
	set @relation_id = @relation_id +1;

	select @relation_id+1,@tabid,rl_related_tabid,rl_name,rl_sequence,rl_label,rl_presence,rl_actions 
	from dual  where not exists(select 1 from ld_relatedlists where tabid=@tabid and related_tabid = rl_related_tabid);

Fetch cur1 into rl_related_tabid,rl_name,rl_sequence,rl_label,rl_presence,rl_actions;
end while loop1;
close cur1;

update ld_relatedlists_seq set id = (select max(relation_id) from ld_relatedlists);

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for CopyPicklistDependency
-- ----------------------------
DROP PROCEDURE IF EXISTS `CopyPicklistDependency`;
DELIMITER ;;
CREATE PROCEDURE `CopyPicklistDependency`(
	copymodule VARCHAR(100),
	tomodule VARCHAR(100)
)
BEGIN

	declare tmp_sourcefield  varchar(100) default '';
	declare tmp_targetfield  varchar(100) default '';
	declare tmp_sourcevalue  varchar(100) default '';
	declare tmp_targetvalues text;
		
	declare mycursor cursor for select sourcefield,targetfield,sourcevalue,targetvalues from ld_picklist_dependency where tabid=(select tabid from ld_tab where `name`=copymodule); 
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_sourcefield = NULL;
	
	select tabid into @tabid from ld_tab where `name`=tomodule;

	open mycursor;
	fetch mycursor into tmp_sourcefield,tmp_targetfield,tmp_sourcevalue,tmp_targetvalues;
	while(tmp_sourcefield is not null) DO
			select max(id) into @id from ld_picklist_dependency;
			delete from ld_picklist_dependency where tabid=@tabid and sourcefield=tmp_sourcefield and targetfield=tmp_targetfield and sourcevalue=tmp_sourcevalue;

			select @id+1,@tabid,tmp_sourcefield,tmp_targetfield,tmp_sourcevalue,tmp_targetvalues;

			fetch mycursor into tmp_sourcefield,tmp_targetfield,tmp_sourcevalue,tmp_targetvalues;
	end while;
	close mycursor;

	update ld_picklist_dependency_seq set id=(select max(id) from ld_picklist_dependency);

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for CopyProducttoolfield
-- ----------------------------
DROP PROCEDURE IF EXISTS `CopyProducttoolfield`;
DELIMITER ;;
CREATE PROCEDURE `CopyProducttoolfield`(
	IN `copymodule` varchar(100),IN `tomodule` varchar(100)
)
BEGIN
	#Routine body goes here...
declare done  int  default 0;
declare is_producttoolfieldid int;
declare is_columnname  varchar (30);
declare is_allowhide varchar(30);
declare is_fieldlabel varchar (50) ;
declare is_defaultvalue varchar (255) ;
declare is_presence int ;
declare is_uitype varchar (19);
declare is_typeofdata varchar(100);
declare is_sequence int;
declare is_tablename varchar (50) ;
declare is_width int ;
declare is_edit_permission int ;
declare is_input_type int;
declare is_fieldid int;
declare is_newline int;
declare is_defaultcolumn int;
declare is_is_checkimportfield int;
declare is_nullfield int;
declare is_description varchar(255);
DECLARE p_cnt int default 0;

declare cur1 CURSOR FOR select producttoolfieldid,columnname,allowhide,fieldlabel,defaultvalue,presence,uitype,typeofdata,sequence,tablename,width,edit_permission,
input_type,fieldid,newline,defaultcolumn,is_checkimportfield,nullfield,description from ld_producttoolfield where tabid = (select tabid from ld_tab where name = copymodule) and uitype != 200 and uitype != 204;
declare continue handler  for not   found  SET done =1;

select tabid into @to_tabid from ld_tab where `name` = tomodule;
select tabid into @copy_tabid from ld_tab where `name` = copymodule;

OPEN cur1;
Fetch cur1 into is_producttoolfieldid,is_columnname,is_allowhide,is_fieldlabel,is_defaultvalue,is_presence,is_uitype,is_typeofdata,is_sequence,is_tablename,is_width,is_edit_permission,
is_input_type,is_fieldid,is_newline,is_defaultcolumn,is_is_checkimportfield,is_nullfield,is_description;
 loop1: while  done<>1 DO
	select count(1) into p_cnt from ld_producttoolfield where columnname = is_columnname and tabid = @to_tabid;

	if p_cnt = 0 then
		select max(producttoolfieldid) into @producttoolfieldid from ld_producttoolfield;
		set @producttoolfieldid = @producttoolfieldid +1;
		-- 插入is_producttoolfield
		input_type,fieldid,newline,defaultcolumn,is_checkimportfield,nullfield,description)
			select @producttoolfieldid,@to_tabid,is_columnname,is_allowhide,is_fieldlabel,is_defaultvalue,is_presence,is_uitype,is_typeofdata,is_sequence,is_tablename,is_width,is_edit_permission,
		is_input_type,is_fieldid,is_newline,is_defaultcolumn,is_is_checkimportfield,is_nullfield,is_description from dual  where not exists(select 1 from ld_producttoolfield where tabid=@to_tabid and columnname = is_columnname);

		-- 分录明细字段公式表
			if is_input_type = 2 THEN
				select @producttoolfieldid,formulastring,columnstring,sequence from ld_producttoolfield_formula where producttoolfieldid = is_producttoolfieldid;
			end if;

		-- 中文插入
		select ld_tranlabel.fieldlabel into @fieldlabel from ld_tranlabel where tabid = @copy_tabid and Relateid = is_producttoolfieldid and trantable = 'ld_producttoolfield' and languagetype = 'zh';
		select 'zh','ld_producttoolfield',@to_tabid,@producttoolfieldid,@fieldlabel from dual where not exists(select 1 from ld_tranlabel where tabid = @to_tabid and Relateid = @producttoolfieldid and languagetype = 'zh' and trantable = 'ld_producttoolfield');
		-- 英文插入
		select ld_tranlabel.fieldlabel into @fieldlabel from ld_tranlabel where tabid = @copy_tabid and Relateid = is_producttoolfieldid and trantable = 'ld_producttoolfield' and languagetype = 'en';
		select 'en','ld_producttoolfield',@to_tabid,@producttoolfieldid,@fieldlabel from dual where not exists(select 1 from ld_tranlabel where tabid = @to_tabid and Relateid = @producttoolfieldid and languagetype = 'en' and trantable = 'ld_producttoolfield');
	end if;
Fetch cur1 into is_producttoolfieldid,is_columnname,is_allowhide,is_fieldlabel,is_defaultvalue,is_presence,is_uitype,is_typeofdata,is_sequence,is_tablename,is_width,is_edit_permission,
is_input_type,is_fieldid,is_newline,is_defaultcolumn,is_is_checkimportfield,is_nullfield,is_description;
end while loop1;
close cur1;

update ld_field_seq set id = (select max(fieldid) from ld_field);

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for crm_publicaccount_recoveryreminds
-- ----------------------------
DROP PROCEDURE IF EXISTS `crm_publicaccount_recoveryreminds`;
DELIMITER ;;
CREATE PROCEDURE `crm_publicaccount_recoveryreminds`()
BEGIN
	declare var_type varchar(100);
	DECLARE var_accountnames text;
	DECLARE var_totalaccounts int(19);
	declare var_smownerid int(19);
	declare done  int  default 0;

   declare cur1 CURSOR FOR select * from ld_publicaccount_remindtableview;
	 declare continue handler  for not   found  SET done =1;
	 OPEN cur1;

	 Fetch cur1 into var_type, var_accountnames,var_totalaccounts,var_smownerid;
	 loop1: while  done<>1 DO
		if var_totalaccounts>0 then
			if var_type='normal' or var_type='singlenormal' THEN
			 set @tmpcontent=concat("您有",var_totalaccounts,"条普通客户未达成目标，回收到公海池。客户名称如下：<br>",var_accountnames);
				call ldcrm_add_reminder(@tmpcontent,var_smownerid,'',0);
			elseif var_type='complete' THEN
				 set @tmpcontent=concat("您有",var_totalaccounts,"条公海客户达成条件后未达成目标，回收到公海池。客户名称如下：<br>",var_accountnames);
				call ldcrm_add_reminder(@tmpcontent,var_smownerid,'',0);
			else
				 set @tmpcontent=concat("您有",var_totalaccounts,"条公海客户未达成公海目标，回收到公海池。客户名称如下：<br>",var_accountnames);
				 call ldcrm_add_reminder(@tmpcontent,var_smownerid,'',0);
			end if;
	end if;
   Fetch cur1 into var_type, var_accountnames,var_totalaccounts,var_smownerid;
	end while loop1;
	close cur1;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for DelColumn
-- ----------------------------
DROP PROCEDURE IF EXISTS `DelColumn`;
DELIMITER ;;
CREATE PROCEDURE `DelColumn`(
	tablename varchar(50),
	columnname varchar(50)
)
begin

	select database() into @tableschema;

	set tablename=lower(tablename);
	set @colName='';
	SET @tsql=CONCAT('select  IFNULL(column_name, '''') into @colName  from information_schema.columns where  TABLE_SCHEMA =','''',@tableschema,'''','  and  table_name= ','''',tablename,'''',' and COLUMN_NAME=','''',columnname,'''');

	prepare stmt from @tsql;
	execute stmt;

	set @coldel=IFNULL(@colName,'-1');

	IF @coldel <> '-1'  and  @coldel=columnname THEN

		set @alterColumn=CONCAT(' alter table ',tablename, ' drop ',columnname);
		prepare stalter from @altercolumn;
		execute stalter;
		deallocate prepare stalter;
	END IF;

	deallocate prepare stmt;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for DelPrikey
-- ----------------------------
DROP PROCEDURE IF EXISTS `DelPrikey`;
DELIMITER ;;
CREATE PROCEDURE `DelPrikey`(
tablename varchar(50)
)
begin

select database() into @tableschema;  -- 获取数据库实体
SET @sql1=CONCAT("select count(column_key) into @del from information_schema.columns where table_schema='",@tableschema,"' and table_name='",tablename,"' and column_key='PRI'");
SET @sql2=CONCAT('alter table ',tablename,' drop primary key');

PREPARE statement_name FROM @sql1; 
EXECUTE statement_name;
DEALLOCATE PREPARE statement_name;

IF @del>0 THEN 
	PREPARE statement_name FROM @sql2; 
	EXECUTE statement_name;
	DEALLOCATE PREPARE statement_name;
END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for Del_ForeignKey
-- ----------------------------
DROP PROCEDURE IF EXISTS `Del_ForeignKey`;
DELIMITER ;;
CREATE PROCEDURE `Del_ForeignKey`(
	tmp_tablename varchar(100),
	tmp_fkeyname varchar(100)
)
BEGIN

	IF EXISTS (SELECT 1 FROM information_schema.KEY_COLUMN_USAGE WHERE CONSTRAINT_NAME=tmp_fkeyname AND TABLE_NAME=tmp_tablename AND TABLE_SCHEMA=DATABASE()) THEN
		SET @execsql=CONCAT(' ALTER TABLE ',tmp_tablename, ' DROP FOREIGN KEY ',tmp_fkeyname);
		PREPARE stmt_execsql FROM @execsql; 
		EXECUTE stmt_execsql;
		DEALLOCATE PREPARE stmt_execsql;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for Del_TableIndex
-- ----------------------------
DROP PROCEDURE IF EXISTS `Del_TableIndex`;
DELIMITER ;;
CREATE PROCEDURE `Del_TableIndex`(
	tmp_tablename varchar(100),
	tmp_indexname varchar(100)
)
BEGIN  

	IF EXISTS (SELECT 1 FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=tmp_tablename AND index_name=tmp_indexname) THEN  
		SET @execsql=CONCAT(' DROP INDEX ',tmp_indexname,' ON ',tmp_tablename);
		PREPARE stmt_execsql FROM @execsql; 
		EXECUTE stmt_execsql;
		DEALLOCATE PREPARE stmt_execsql;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for execute_account_publicoperation
-- ----------------------------
DROP PROCEDURE IF EXISTS `execute_account_publicoperation`;
DELIMITER ;;
CREATE PROCEDURE `execute_account_publicoperation`()
BEGIN
	select `status` into @status  from ld_account_set;


	if @status=0   then
		select eventdate into @eventdate from ld_sys_event where type='publicaccount' ORDER BY eventdate DESC LIMIT 1;
		if @eventdate!=CURDATE() then
			 update  ld_sys_event set eventdate=now() where type='publicaccount';
				call  account_nocomplete_recoveryrule();
				call  account_complete_recoveryrule();
				call account_normal_recoveryrule();
			call account_singlenormal_recoveryrule();
		end if;

	end if;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for fieldintoprofile
-- ----------------------------
DROP PROCEDURE IF EXISTS `fieldintoprofile`;
DELIMITER ;;
CREATE PROCEDURE `fieldintoprofile`(
profileid int(19),
tabname varchar(50)
)
begin
    declare done  int  default 0;
	declare ttabid  int ;
	declare ffieldid int ;
	declare cur2 CURSOR FOR SELECT fieldid,tabid   FROM  ld_field where tabid in(select tabid from ld_tab where name=tabname);
	declare continue handler  for not   found  SET done =1;

	OPEN cur2;
	Fetch cur2 into ffieldid,ttabid;

 	loop1: while  done<>1 DO
		set @sql=Concat('insert into ld_profile2field(profileid,tabid,fieldid,visible,readonly) select ',profileid,',',ttabid,',',ffieldid,',',0,',',0 ,' from dual where not exists(select 1 from ld_profile2field where fieldid=',ffieldid,' and profileid=',profileid,')');

		prepare stmt from @sql;
	      execute stmt;
	      deallocate  prepare  stmt;
		Fetch cur2 into ffieldid,ttabid;
	end while loop1;
	close cur2;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for fieldprofile
-- ----------------------------
DROP PROCEDURE IF EXISTS `fieldprofile`;
DELIMITER ;;
CREATE PROCEDURE `fieldprofile`(
 tabname varchar(50)
)
begin

	declare done  int  default 0;
	declare ttabid  int ;
	declare ffieldid int ;
	declare cur1 CURSOR FOR SELECT fieldid,tabid   FROM  ld_field where tabid in(select tabid from ld_tab where name=tabname);
	declare continue handler  for not   found  SET done =1;

	OPEN cur1;
	Fetch cur1 into ffieldid,ttabid;

 	loop1: while  done<>1 DO
		set @sql=Concat('insert into ld_def_org_field(tabid,fieldid,visible,readonly) select ',ttabid,',',ffieldid,',',0,',',1 ,' from dual where not exists(select 1 from ld_def_org_field where fieldid=',ffieldid,')');

		prepare stmt from @sql;
	      execute stmt;
	      deallocate  prepare  stmt;
		Fetch cur1 into ffieldid,ttabid;
	end while loop1;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for getallprofile
-- ----------------------------
DROP PROCEDURE IF EXISTS `getallprofile`;
DELIMITER ;;
CREATE PROCEDURE `getallprofile`(

 tabname varchar(50)
)
begin

	declare done  int  default 0;
	declare pdone int default 0;
	declare ttabid  int ;
	declare ffieldid int ;
	declare pprofileid int;


declare cur2 CURSOR FOR SELECT profileid   FROM  ld_profile;

declare continue handler  for not   found  SET done =1;


	open cur2;
	fetch cur2 into pprofileid;
	loop2: while  done<>1 DO

		call fieldintoprofile(pprofileid,tabname);
		fetch cur2 into pprofileid;
	end while loop2;
	close cur2;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for insert_tmp_date
-- ----------------------------
DROP PROCEDURE IF EXISTS `insert_tmp_date`;
DELIMITER ;;
CREATE PROCEDURE `insert_tmp_date`(
)
begin

	declare tmpdate date default NULL;
	
	set @cnt=0;
	set @maxdate=NULL;
	set @mindate=NULL;
	set @enddate=NULL;
	select ifnull(max(date),CURDATE()) into @maxdate from tmp_date;
	select 
		date_sub(ifnull(min(date),CURDATE()),INTERVAL 1 year) into @mindate
	from (
			select min(cashbilldate) date from ld_cashbill
			UNION ALL select min(signed_data) from ld_salesorder
			UNION ALL select min(due_date) from ld_servicecontracts) a;

	select date_add(CURDATE(),interval 2 YEAR) into @enddate;
	select count(1) into @cnt from tmp_date;

	IF @cnt=0 THEN
		set tmpdate=@mindate;
	ELSE
		set tmpdate=date_add(@maxdate,interval 1 day);
	END IF;

	while tmpdate<=@enddate DO 
			set tmpdate=date_add(tmpdate,interval 1 day);
	end while; 

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_reminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_reminder`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_add_reminder`(
	tmp_content text,
	tmp_recieverid int(19),
    tmp_reltab varchar(100),
	tmp_related_to int(19)
    
)
BEGIN
	
	set @maxid=0;
	select max(crmid) into @maxid from ld_crmentity;
	select @maxid+1,'Reminds';			
	select @maxid+1,tmp_content,now(),tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,0,0,0,0,now(),now(),null,0;

	update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_add_sms
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_add_sms`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_add_sms`(
	tmp_mobile VARCHAR(50),
	tmp_jieshouren VARCHAR(255),
	tmp_content TEXT,
	tmp_sendtime DATETIME,
	tmp_sender VARCHAR(100),
	tmp_relatedid INT(19)
)
BEGIN

	SET @cnt=(SELECT COUNT(SubmitTime) FROM ld_smssend WHERE DATE_FORMAT(SubmitTime,'%Y-%m-%d')=CURDATE());

		TaskID,
		BatchNo,
		CalledNumber,
		SmsContent,
		SubmitTime,
		CreateTime,
		SmsResult,
		SmsBillingFee,
		operator,
		ReceiveContacts,
		FDataStatu,
		relatieid
	)
	SELECT
		IFNULL((SELECT MAX(TaskID) FROM ld_smssend),0)+1,
		CONCAT('sms',DATE_FORMAT(NOW(),'%Y%m%d'),LPAD(@cnt+1,8,0)),
		tmp_mobile,
		tmp_content,
		tmp_sendtime,
		NOW(),
		0,
		0.00,
		tmp_sender,
		tmp_jieshouren,
		0,
		tmp_relatedid;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_read_tmpreminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_read_tmpreminder`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_read_tmpreminder`(
)
BEGIN

	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';
	DECLARE tmp_recieverid INT(19) DEFAULT 0;
	DECLARE tmp_remindtime datetime;
	DECLARE tmp_reltab varchar(100) DEFAULT '';
	DECLARE tmp_related_to INT(19) DEFAULT 0;
	DECLARE tmp_ruleid INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR 
		SELECT
			id,
			content,
			reminderid,
			remindtime,
			reltab,
			related_to,
			reminds_ruleid 
		FROM ld_tmpreminder 
		WHERE remindtime<=NOW() 
			AND IFNULL(content,'') not like '%[var.%'
		ORDER BY remindtime DESC LIMIT 50;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	WHILE (tmp_id IS NOT NULL) DO
		DELETE FROM ld_tmpreminder WHERE id=tmp_id;
		set @maxid=0;
		select max(crmid) into @maxid from ld_crmentity;
		select @maxid+1,'Reminds';
		
		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			
		select @maxid+1,tmp_content,tmp_remindtime,tmp_recieverid,'未读',tmp_related_to,tmp_reltab,0,0,tmp_ruleid,0,0,0,tmp_remindtime,tmp_remindtime,null,0;

	FETCH Mycur INTO tmp_id,tmp_content,tmp_recieverid,tmp_remindtime,tmp_reltab,tmp_related_to,tmp_ruleid;
	END WHILE;
	CLOSE Mycur;	
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_update_attachments_notes
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_update_attachments_notes`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_update_attachments_notes`(
)
BEGIN

	DECLARE tmp_crmid INT(19) DEFAULT 0;
	DECLARE tmp_attid INT(19) DEFAULT 0;

	DECLARE mycursor CURSOR FOR 
				SELECT
					b.crmid,
					b.attachmentsid
				FROM ld_notes a
				INNER JOIN ld_seattachmentsrel b ON a.notesid=b.crmid
				ORDER BY b.crmid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_crmid = NULL;
	
	OPEN mycursor;
	FETCH mycursor INTO tmp_crmid,tmp_attid;
	WHILE(tmp_crmid IS NOT NULL) DO
		SET @sql1=CONCAT("UPDATE ld_attachments SET `name`=REPLACE(`name`,'",tmp_crmid,"_','",tmp_attid,"_') WHERE attachmentsid=",tmp_attid);
		PREPARE stalter FROM @sql1;
		EXECUTE stalter;
		FETCH mycursor INTO tmp_crmid,tmp_attid;
	END WHILE;
	CLOSE mycursor;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_update_sykq_all
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_all`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_update_sykq_all`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE mycursor CURSOR FOR 
			SELECT DISTINCT smownerid FROM ld_addjobbill
			UNION 
			SELECT DISTINCT smownerid FROM ld_minusjobbill ORDER BY smownerid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' SET tmp_id = NULL;

	OPEN mycursor;
	Fetch mycursor INTO tmp_id;
	WHILE(tmp_id IS NOT NULL) DO
		CALL ldcrm_update_sykq_byuserid(tmp_id);
		Fetch mycursor INTO tmp_id;
	END WHILE;
	CLOSE mycursor;
END
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_update_sykq_bycrmid
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_bycrmid`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_update_sykq_bycrmid`(
	tmp_id int(19)
)
BEGIN

	IF EXISTS (SELECT 1 FROM ld_crmentity WHERE crmid=tmp_id AND setype='MinusJobBill') THEN
		UPDATE ld_minusjobbill a
		LEFT JOIN ld_minusjobbillscf b ON a.minusjobbillid=b.minusjobbillid
		LEFT JOIN (
			SELECT
				a.id, 
				a.last_name,
				IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
					-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
						0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
						0
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
						5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
						10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
						15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					ELSE 112
				END AS total_sy_nj
			FROM (
				SELECT
						a.id,
						a.last_name,
						a.`status`,
						a.hire_date,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
							ELSE
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
						END AS this_njstart,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							ELSE
								DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
						END AS extra_njend
					FROM ld_users a
			) a
		) t ON a.smownerid=t.id
		SET b.sytx=t.total_sy_tx,b.synj=t.total_sy_nj
		WHERE b.minusjobbillid=tmp_id;
	ELSE 
		UPDATE ld_addjobbill a
		LEFT JOIN ld_addjobbillscf b ON a.addjobbillid=b.addjobbillid
		LEFT JOIN (
			SELECT
				a.id, 
				a.last_name,
				IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
					-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
				CASE
					WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
						0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
						0
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
						5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
						10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
						15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
					ELSE 112
				END AS total_sy_nj
			FROM (
				SELECT
						a.id,
						a.last_name,
						a.`status`,
						a.hire_date,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
							ELSE
								DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
						END AS this_njstart,
						CASE
							WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
							ELSE
								DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
						END AS extra_njend
					FROM ld_users a
			) a
		) t ON a.smownerid=t.id
		SET b.sytx=t.total_sy_tx,b.synj=t.total_sy_nj
		WHERE b.minusjobbillid=tmp_id;
	END IF;
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for ldcrm_update_sykq_byuserid
-- ----------------------------
DROP PROCEDURE IF EXISTS `ldcrm_update_sykq_byuserid`;
DELIMITER ;;
CREATE PROCEDURE `ldcrm_update_sykq_byuserid`(
	tmp_id int(19)
)
BEGIN
  
    select minusjobbillid from ld_minusjobbill where minusjobbillid not in (select minusjobbillid from ld_minusjobbillscf);
    
	-- 更新请假单上的剩余调休和剩余年假
	UPDATE ld_minusjobbill a
	LEFT JOIN ld_minusjobbillscf b ON a.minusjobbillid=b.minusjobbillid
	LEFT JOIN (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t ON a.smownerid=t.id
	SET b.sytx=t.total_sy_tx,b.synj=concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;


    select addjobbillid from ld_addjobbill where addjobbillid not in (select addjobbillid from ld_addjobbillscf);

	-- 更新加班单上的剩余调休和剩余年假
	UPDATE ld_addjobbill a
	LEFT JOIN ld_addjobbillscf b ON a.addjobbillid=b.addjobbillid
	LEFT JOIN (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t ON a.smownerid=t.id
	SET b.sytx=t.total_sy_tx,b.synj=concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),''))
	WHERE a.smownerid=tmp_id;
	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for splitstr
-- ----------------------------
DROP PROCEDURE IF EXISTS `splitstr`;
DELIMITER ;;
CREATE PROCEDURE `splitstr`(s_str varchar(128), s_split varchar(3))
begin

	drop table if exists splitstrlist;
	create temporary table splitstrlist( str varchar(100));
  set @i = length(s_str) - length(replace(s_str,s_split,''));  -- 算出分隔符的总数
  set @left_str = s_str;
  while @i>0                -- 有多少个分隔符就循环多少遍
  do
  set @sub_str = substr(@left_str,1,instr(@left_str,s_split)-1);            -- 得到分隔符前面的字符串
  set @left_str = substr(@left_str,length(@sub_str)+length(s_split)+1);     -- 得到分隔符后面的字符串
  set @n = trim(@sub_str);
  set @i = @i - 1;
  end while;
  set @n = trim(@left_str);
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for task_accounts_remind_lastservicedate
-- ----------------------------
DROP PROCEDURE IF EXISTS `task_accounts_remind_lastservicedate`;
DELIMITER ;;
CREATE PROCEDURE `task_accounts_remind_lastservicedate`(
)
BEGIN
	

	declare tmp_accountid int(19) default 0;
	declare tmp_accountname varchar(255) default NULL;
	declare tmp_date date default NULL;
	declare tmp_recieverid int(19) default 0;
	declare tmp_days int(19) default 0;

	declare cur1 cursor for SELECT 
								accountid,
								accountname,
								lastservicedate,
								smownerid,
								DATEDIFF(lastservicedate,CURDATE()) AS days
							FROM ld_account
							WHERE deleted=0
								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;

	OPEN cur1;
	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	while(tmp_accountid is not null) DO
		IF tmp_days<=-30 THEN
			SET @remind_type='自动任务之服务过期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='Accounts' and content like '自动任务之服务过期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经过期',abs(tmp_days),'天（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				select @maxid+1,'Reminds';			
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN
			SET @remind_type='自动任务之服务到期提醒';
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='Accounts' and content like '自动任务之服务到期提醒%') THEN
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'服务已经到期（',tmp_date,'），请及时跟进！');

				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				select @maxid+1,'Reminds';			
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN
			SET @remind_type='自动任务之服务即将到期提醒';
			
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='Accounts' and content like '自动任务之服务即将到期提醒%') THEN
				
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'还有',abs(tmp_days),'天（',tmp_date,'）即将到期，请及时跟进！');
				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				select @maxid+1,'Reminds';			
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'Accounts',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		END IF;
		
		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	end while;
	close cur1;


end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for task_dailyreport_reminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `task_dailyreport_reminder`;
DELIMITER ;;
CREATE PROCEDURE `task_dailyreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(dailyreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;
	
	SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '日报提交提醒：%' AND DATE_FORMAT(date_time,'%Y-%m-%d')=CURDATE();

	IF @remind<>'不提醒' AND WEEKDAY(NOW())<5 AND @cnt=0 AND DATE_FORMAT(DATE_ADD(NOW(),INTERVAL 1 HOUR),'%H:%i')>=@remind AND DATE_FORMAT(NOW(),'%H:%i')<=@remind THEN
		OPEN Mycur;
		FETCH Mycur INTO tmp_id;
		WHILE (tmp_id IS NOT NULL) DO
			IF NOT EXISTS (SELECT 1 FROM ld_dailyreport WHERE startdate=CURDATE() AND dstatus=1 AND smcreatorid=tmp_id) THEN
				SET @content=CONCAT('日报提交提醒：您该提交日报啦，还有一个小时就到提交期限哦');
				CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
			END IF;
		FETCH Mycur INTO tmp_id;
		END WHILE;
		CLOSE Mycur;	
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for task_gonggao_reminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `task_gonggao_reminder`;
DELIMITER ;;
CREATE PROCEDURE `task_gonggao_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;
	DECLARE tmp_userid INT(19) DEFAULT 0;
	DECLARE tmp_content text DEFAULT '';

	DECLARE Mycur CURSOR FOR
		SELECT 
			a.publicannouncementid,
			b.userid
		FROM ld_publicannouncement a
		LEFT JOIN ld_publicannouncement_reminds b ON a.publicannouncementid=b.crmid
		WHERE a.deleted=0
			AND CURDATE() BETWEEN startdate AND enddate
			AND NOT EXISTS (SELECT 1 FROM ld_reminds WHERE related_to=a.publicannouncementid AND recieverid=b.userid AND content like '公告提醒：有新的公告，请及时关注！');

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	OPEN Mycur;
	FETCH Mycur INTO tmp_id,tmp_userid;
	WHILE (tmp_id IS NOT NULL) DO
		SET @content='公告提醒：有新的公告，请及时关注！';
		CALL ldcrm_add_reminder(@content,tmp_userid,'PublicAnnouncement',tmp_id);
		FETCH Mycur INTO tmp_id,tmp_userid;
	END WHILE;
	CLOSE Mycur;	
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for task_monthreport_reminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `task_monthreport_reminder`;
DELIMITER ;;
CREATE PROCEDURE `task_monthreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(monthreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;

	IF @remind<>'不提醒' THEN
		IF @remind>=20 AND @remind<32 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(DAY(CURDATE())>=@remind-2 AND DAY(CURDATE())<=@remind,1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);
			SET @days=@remind-DAY(CURDATE())+1;
		ELSEIF @remind=40 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(DATE_ADD(CURDATE(),INTERVAL 2 DAY)>=LAST_DAY(CURDATE()),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_SUB(LAST_DAY(CURDATE()),INTERVAL 2 DAY);	
			SET @days=DATEDIFF(LAST_DAY(CURDATE()),CURDATE())+1;
		ELSEIF @remind<=2 AND DAY(CURDATE())>=25 THEN
			SET @yue=MONTH(CURDATE());
			SET @do_remind=IF(CURDATE()>=DATE_ADD(LAST_DAY(CURDATE()),INTERVAL @remind-2 DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(LAST_DAY(CURDATE()),INTERVAL @remind-2 DAY);	
			SET @days=DATEDIFF(DATE_ADD(LAST_DAY(CURDATE()), INTERVAL @remind DAY),CURDATE())+1;
		ELSEIF @remind<=2 AND DAY(CURDATE()) IN (1,2) THEN
			SET @yue=MONTH(CURDATE())-1;
			SET @do_remind=IF(CURDATE()<=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE()) DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);	
			SET @days=DATEDIFF(DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE()) DAY),CURDATE())+1;
		ELSEIF @remind>=3 AND @remind<=5 THEN
			SET @yue=MONTH(CURDATE())-1;
			SET @do_remind=IF(CURDATE()>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY) AND CURDATE()<=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(curdate()) DAY),1,0);
			SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '月报提交提醒：%' AND date_time>=DATE_ADD(CURDATE(),INTERVAL @remind-DAY(CURDATE())-2 DAY);
			SET @days=DATEDIFF(DATE_ADD(CURDATE(),INTERVAL @remind-DAY(curdate()) DAY),CURDATE())+1;
		ELSE 
				SET @do_remind=0;
		END IF;

		IF @do_remind=1 AND @cnt=0 THEN 
			OPEN Mycur;
			FETCH Mycur INTO tmp_id;
			WHILE (tmp_id IS NOT NULL) DO
				IF NOT EXISTS (SELECT 1 FROM ld_monthreport WHERE monthofyear=@yue AND `Status`=1 AND smcreatorid=tmp_id) THEN
					IF @days=1 THEN
						SET @content=CONCAT('月报提交提醒：您该提交月报啦，今天就是提交期限哦');
					ELSE
						SET @content=CONCAT('月报提交提醒：您该提交月报啦，还有',@days,'天就是提交期限哦');
					END IF;
					CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
				END IF;
			FETCH Mycur INTO tmp_id;
			END WHILE;
			CLOSE Mycur;	
		END IF;
	END IF;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for task_servicecharge_remind_lastservicedate
-- ----------------------------
DROP PROCEDURE IF EXISTS `task_servicecharge_remind_lastservicedate`;
