				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN
			SET @remind_type='自动任务之服务即将到期提醒';
			
			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab='ServiceCharge' and content like '自动任务之服务即将到期提醒%') THEN
				
				set @content=concat(@remind_type,'，您的客户',tmp_accountname,'还有',abs(tmp_days),'天（',tmp_date,'）即将到期，请及时跟进！');
				set @maxid=0;
				select max(crmid) into @maxid from ld_crmentity;
				select @maxid+1,'Reminds';			
				select @maxid+1,@content,now(),tmp_recieverid,'未读',tmp_accountid,'ServiceCharge',0,0,0,1,1,1,now(),now(),null,0;
			
				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);
			END IF;
		END IF;
		
		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;
	end while;
	close cur1;


end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for task_weekreport_reminder
-- ----------------------------
DROP PROCEDURE IF EXISTS `task_weekreport_reminder`;
DELIMITER ;;
CREATE PROCEDURE `task_weekreport_reminder`(
)
BEGIN
	
	DECLARE tmp_id INT(19) DEFAULT 0;

	DECLARE Mycur CURSOR FOR
		SELECT DISTINCT
			a.id
		FROM ld_users a
		LEFT JOIN ld_profile2standardpermissions c ON c.profileid=a.profileid
		LEFT JOIN ld_tab d ON d.tabid=c.tabid
		WHERE d.`name`='ReportLog'
			AND permissions=0
			AND a.`status`='Active';

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_id = NULL;

	SET @remind='不提醒';
	SELECT IFNULL(weekreminddate,'不提醒') INTO @remind FROM ld_workremindset LIMIT 1;

	SELECT count(1) into @cnt FROM ld_reminds WHERE content LIKE '周报提交提醒：%' AND WEEK(date_time)=WEEK(CURDATE());

	IF @remind<>'不提醒' AND WEEKDAY(NOW())IN (@remind-2,@remind-1) AND @cnt=0 THEN
		OPEN Mycur;
		FETCH Mycur INTO tmp_id;
		WHILE (tmp_id IS NOT NULL) DO
			IF NOT EXISTS (SELECT 1 FROM ld_weekreport WHERE Weeksofyear=WEEK(CURDATE()) AND yearbol=YEAR(CURDATE()) AND `status`=1 AND smcreatorid=tmp_id) THEN
				IF WEEKDAY(NOW())=@remind-2 THEN
					SET @content=CONCAT('周报提交提醒：您该提交周报啦，明天是最后一天期限哦');
				ELSEIF WEEKDAY(CURDATE())=@remind-1 THEN
					SET @content=CONCAT('周报提交提醒：您该提交周报啦，今天是最后一天期限哦');
				END IF;
				CALL ldcrm_add_reminder(@content,tmp_id,'ReportLog',0);
			END IF;
		FETCH Mycur INTO tmp_id;
		END WHILE;
		CLOSE Mycur;	
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_account_lastcontactuser
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_account_lastcontactuser`;
DELIMITER ;;
CREATE PROCEDURE `update_account_lastcontactuser`(
)
BEGIN
	
	
		declare tmp_accountid int;
		declare tmp_smownerid int;

		declare cur1 CURSOR FOR select b.accountid,a.smownerid
														from (
																select 
																accountid,smownerid,max(contactdate) as contactdate
																from ld_contactrecords 
																where deleted=0 and accountid>0 
																GROUP BY accountid
																order by accountid, contactdate DESC) a 
														INNER JOIN ld_account b on a.accountid=b.accountid
														where b.lastcontactuser=0 and a.smownerid>0;

		DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
	
		OPEN cur1;
		Fetch cur1 into tmp_accountid,tmp_smownerid;
		while(tmp_accountid is not null) DO
				update ld_account set lastcontactuser=tmp_smownerid where lastcontactuser=0 and accountid=tmp_accountid;
		Fetch cur1 into tmp_accountid,tmp_smownerid;
		end while;
		close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_account_lastservicedate
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_account_lastservicedate`;
DELIMITER ;;
CREATE PROCEDURE `update_account_lastservicedate`(
)
begin

	declare tmp_accountid int default 0;

	declare cur2 CURSOR FOR select accountid from ld_account;
	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_accountid = NULL;
	
	open cur2;
	fetch cur2 into tmp_accountid;
	while(tmp_accountid is not null) DO
		set @service_enddate=NULL;
		select max(service_enddate) into @service_enddate from ld_maxservicedate where accountid=tmp_accountid;
		
		IF @service_enddate is not NULL THEN
			update ld_account set lastservicedate=@service_enddate where accountid=tmp_accountid;
		ELSE
			set @signed_data=NULL;
			SELECT max(signed_data) into @signed_data FROM ld_salesorder WHERE accountid=tmp_accountid and ifnull(sostatus,'')<>'已作废' and IFNULL(approvestatus,'')<>'已拒绝';
			IF @signed_data is not NULL THEN
				update ld_account set lastservicedate=@signed_data where accountid=tmp_accountid;
			ELSE
				update ld_account set lastservicedate=DATE_FORMAT(createdtime,'%Y-%m-%d') where accountid=tmp_accountid;
			END IF;
		END IF;

		Fetch cur2 into tmp_accountid;
	end while;
	close cur2;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_cashbill2paymentplan_entitytype
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_cashbill2paymentplan_entitytype`;
DELIMITER ;;
CREATE PROCEDURE `update_cashbill2paymentplan_entitytype`(
)
begin

	set @cnt=0;
	select count(1) into @cnt from ld_cashbill2paymentplan where entitytypeid>0 and LENGTH(ifnull(entitytype,''))<1;
	IF @cnt>0 THEN

		update ld_cashbill2paymentplan a
		LEFT JOIN ld_crmentity b on a.entitytypeid=b.crmid
		set a.entitytype=b.setype
		where a.entitytypeid>0 and LENGTH(ifnull(a.entitytype,''))<1;

	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_invoice_receivedamount_byinvoiceid
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_invoice_receivedamount_byinvoiceid`;
DELIMITER ;;
CREATE PROCEDURE `update_invoice_receivedamount_byinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_invoice WHERE invoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		-- 没有多币种
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE invoiceid=tmp_invoiceid;
	ELSE
		-- 有多币种,计算已收时统一转换为人民币计算
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_paymentplan WHERE deleted=0 AND entitytypeid=tmp_invoiceid AND actualamount>0;
		UPDATE ld_invoice SET received_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE invoiceid=tmp_invoiceid;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_products_ststus1
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_products_ststus1`;
DELIMITER ;;
CREATE PROCEDURE `update_products_ststus1`(

)
begin

	declare done  int  default 0;
	declare tmpproductid int default 0;

	-- 因为不知道资产状态时哪个字段，已“备注”字段为例做说明。
	declare tmpdescription varchar(200) default null;

	-- 按照每个资产去循环更新资产的状态，如果“资产状态”是自定义字段，这个查询需要跟ld_productscf做个表连接
	declare curw CURSOR FOR SELECT productid,description FROM  ld_products;

	declare continue handler  for not   found  SET done =1;

	OPEN curw;
		Fetch curw into tmpproductid,tmpdescription;
		loop1: while  done<>1 DO
			
			-- 按照签约日期查询该资产最近的一个未删除、已审批的合同订单，
			set @salesorderid=0;
			SELECT
			ld_salesorder.salesorderid into @salesorderid
			FROM
				ld_salesorder
			LEFT JOIN ld_inventoryproductrel on ld_salesorder.salesorderid=ld_inventoryproductrel.id
			where ld_salesorder.deleted=0 and ld_salesorder.approvestatus='已批准'
			and ld_inventoryproductrel.productid=tmpproductid order by ld_salesorder.signed_data desc limit 1;

			IF @salesorderid>0 THEN
			
				-- 如果该产品有销售合同，找该产品、该销售合同对应的服务合同，找服务到期日最晚的一个
				-- 需要在做服务合同的关联销售合同
				set @service_end_date=NULL;
				SELECT
				ifnull(ld_inventoryproductrel.servicecontracts_end_date,'1900-01-01') into @service_end_date
				FROM
					ld_servicecontracts
				LEFT JOIN ld_inventoryproductrel on ld_servicecontracts.servicecontractsid=ld_inventoryproductrel.id
				where ld_servicecontracts.deleted=0 
				and ld_inventoryproductrel.productid=tmpproductid order by ld_inventoryproductrel.servicecontracts_end_date desc limit 1;
				
				IF @service_end_date='1900-01-01' THEN
					-- 如果没有服务合同，则更新状态为“已售”
					update ld_products set description='已售' where productid=tmpproductid;
				
				ELSEIF @service_end_date>=CURDATE() THEN
					-- 如果有服务到期日期，并且服务到期日大当前日期，则更新状态到初始状态“已租”
					update ld_products set description='已租' where productid=tmpproductid;
					
				ELSE
					-- 否则服务到期日小于当前日期，更新状态为初始状态
					update ld_products set description='待售租' where productid=tmpproductid;
				END IF;
			
			ELSE
				-- 没有合同订单，同样更新资产状态为初始状态
				update ld_products set description='待售租' where productid=tmpproductid;
			END IF;

		Fetch curw into tmpproductid,tmpdescription;
		end while loop1;
	close curw;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_purchaseinvoice_receivedamount_bypurchaseinvoiceid
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_purchaseinvoice_receivedamount_bypurchaseinvoiceid`;
DELIMITER ;;
CREATE PROCEDURE `update_purchaseinvoice_receivedamount_bypurchaseinvoiceid`(
	tmp_invoiceid INT(19)
)
BEGIN

	SET @cnt1=0;
	SELECT
		count(1) INTO @cnt1
	FROM (
		SELECT IFNULL(currency_id,1) AS currency_id FROM ld_purchaseinvoice WHERE purchaseinvoiceid=tmp_invoiceid
		UNION
		SELECT IFNULL(currency_id,1) FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0
		UNION
		SELECT 
			IFNULL(a.currency_id,1)
		FROM ld_sendcashbill a
		LEFT JOIN ld_sendcashbill2payment b ON a.sendcashbillid=b.sendcashbillid
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=84)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END)
	) a;

	IF @cnt=1 THEN
		-- 没有多币种
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount) INTO @dir_cashtotal
		FROM ld_sendcashbill a
		LEFT JOIN ld_sendcashbill2payment b ON a.sendcashbillid=b.sendcashbillid
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=84)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount) INTO @indir_cashtotal FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0;
		UPDATE ld_purchaseinvoice SET pay_amount=IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0) WHERE purchaseinvoiceid=tmp_invoiceid;
	ELSE
		-- 有多币种,计算已收时统一转换为人民币计算
		SET @dir_cashtotal=0;
		SET @indir_cashtotal=0;
		SELECT 
			SUM(b.amount/IFNULL(a.conversion_rate,1)) INTO @dir_cashtotal
		FROM ld_cashbill a
		LEFT JOIN ld_cashbill2paymentplan b ON a.cashbillid=b.CashBillID
		WHERE a.deleted=0
			AND b.entitytypeid=tmp_invoiceid
			AND (
				CASE
					WHEN (SELECT deploy_value FROM ld_systems_deploy WHERE deploy_type=83)=1 THEN a.checkoutstatus='已审核'
					ELSE 1=1
				END);

		SELECT SUM(actualamount/IFNULL(conversion_rate,1)) INTO @indir_cashtotal FROM ld_sendpayment WHERE deleted=0 AND Purchaseorder_id=tmp_invoiceid AND IFNULL(actualamount,0)>0;
		UPDATE ld_purchaseinvoice SET pay_amount=(IFNULL(@dir_cashtotal,0)+IFNULL(@indir_cashtotal,0))*IFNULL(conversion_rate,1) WHERE purchaseinvoiceid=tmp_invoiceid;
	END IF;

end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_purs_total
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_purs_total`;
DELIMITER ;;
CREATE PROCEDURE `update_purs_total`(
	tmp_sendcashbillid INT(19)
)
BEGIN
	
	declare tmp_entitytypeid int default 0;
	declare tmp_entitytype varchar(200) default NULL;
	
	declare cur1 CURSOR FOR SELECT DISTINCT
										entitytypeid,
										entitytype
									FROM (
										select
											b.entitytypeid,
											b.entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1 and a.sendcashbillid=tmp_sendcashbillid
										UNION
										select 
												c.Purchaseorder_id,
												'PurchaseOrder' entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										INNER JOIN ld_sendpayment c on c.sendpaymentid=b.entitytypeid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1 and a.sendcashbillid=tmp_sendcashbillid) a
									ORDER BY entitytypeid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_entitytypeid = NULL;
	
	select ifnull(deploy_value,0) into @deploy_value from ld_systems_deploy where deploy_type=84;
	select ifnull(deploy_value,0) into @approve_deploy_value from ld_systems_deploy where deploy_type=134;
	
	OPEN cur1;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	while(tmp_entitytypeid is not null) DO
	
		set @tmp_entitytypeid=0;
		set @tmp_entitytypeid=tmp_entitytypeid;
		
		set @cnt1=0;
		select 
			count( DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_purchaseorder where purchaseorderid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_purchaseinvoice where purchaseinvoiceid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_stock where stock_id=@tmp_entitytypeid 
			UNION ALL	
				select currency_id from ld_sendpayment where sendpaymentid=@tmp_entitytypeid
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
				where a.deleted=0 and c.Purchaseorder_id=@tmp_entitytypeid and c.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) c;
					
		-- 如果没有多币种的收款
		IF @cnt1=1 THEN
		      set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.Purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total,2)+round(@purs_total2,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total,2),pay_balance=round(Amount-round(@purs_total,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
			
			
		-- 如果有多币种的收款	
		ELSE

				set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(e.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001) and IF(a.approvestatus = '已拒绝',0,1) <> IF(@approve_deploy_value=1,0.0001,0)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total*conversion_rate,2)+round(@purs_total2*conversion_rate,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total*conversion_rate,2),pay_balance=round(Amount-round(@purs_total*conversion_rate,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
		END IF;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	end while;
	close cur1;
end
;;
DELIMITER ;

-- ----------------------------
-- Procedure structure for update_purs_total1
-- ----------------------------
DROP PROCEDURE IF EXISTS `update_purs_total1`;
DELIMITER ;;
CREATE PROCEDURE `update_purs_total1`(
)
BEGIN
	
	declare tmp_entitytypeid int default 0;
	declare tmp_entitytype varchar(200) default NULL;
	
	declare cur1 CURSOR FOR SELECT DISTINCT
										entitytypeid,
										entitytype
									FROM (
										select
											b.entitytypeid,
											b.entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1
										UNION
										select 
												c.Purchaseorder_id,
												'PurchaseOrder' entitytype
										from ld_sendcashbill a 
										LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
										INNER JOIN ld_sendpayment c on c.sendpaymentid=b.entitytypeid
										where a.deleted=0 and b.entitytypeid>0 and length(b.entitytype)>1) a
									ORDER BY entitytypeid;

	DECLARE CONTINUE HANDLER FOR SQLSTATE '02000' set tmp_entitytypeid = NULL;
	
	select ifnull(deploy_value,0) into @deploy_value from ld_systems_deploy where deploy_type=84;
	
	OPEN cur1;
	Fetch cur1 into tmp_entitytypeid,tmp_entitytype;
	while(tmp_entitytypeid is not null) DO
	
		set @tmp_entitytypeid=0;
		set @tmp_entitytypeid=tmp_entitytypeid;
		
		set @cnt1=0;
		select 
			count( DISTINCT currency_id) into @cnt1 
		from (
			select currency_id from ld_purchaseorder where purchaseorderid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_purchaseinvoice where purchaseinvoiceid=@tmp_entitytypeid
			UNION ALL
				select currency_id from ld_stock where stock_id=@tmp_entitytypeid 
			UNION ALL	
				select currency_id from ld_sendpayment where sendpaymentid=@tmp_entitytypeid
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			UNION ALL
				select 
					a.currency_id 
				from ld_sendcashbill a
				LEFT JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
				where a.deleted=0 and c.Purchaseorder_id=@tmp_entitytypeid and c.deleted=0
					and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) c;
					
		-- 如果没有多币种的收款
		IF @cnt1=1 THEN
		  set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total,2)+round(@purs_total2,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
			ELSEIF tmp_entitytype='Stock' THEN
				update ld_stock set pay_amount=round(@purs_total,2),pay_balance=round(total-round(@purs_total,2),2),sendcashbilldate=@purs_date where stock_id=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='SendPayment' THEN
				update ld_sendpayment set Actualamount=round(@purs_total,2),pay_balance=round(Amount-round(@purs_total,2),2),Actualdate=@purs_date where sendpaymentid=@tmp_entitytypeid;
			END IF;
			
			
		-- 如果有多币种的收款	
		ELSE

            set @purs_total=0.00;
			set @purs_date='0000-00-00';
			set @purs_total2=0.00;
			set @purs_date2='0000-00-00';
			
			select
				sum(h.amount) into @purs_total
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				where h.entitytypeid=@tmp_entitytypeid
				group by h.entitytypeid;

			select
				max(a.cashbilldate) into @purs_date
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			where a.deleted=0 and b.entitytypeid=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by b.entitytypeid;
			
			-- 计算采购订单已收金额时，需要考虑订单对应的回款计划的收款
			select
				sum(h.amount) into @purs_total2
			from (
				select 
					a.sendcashbillid,
					b.entitytypeid,
					b.amount/a.conversion_rate as amount
				from ld_sendcashbill a 
				INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
				where a.deleted=0 and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
				UNION ALL
				select * from (
					select 
						e.sendcashbillid,
						f.entitytypeid,
						e.nosendpayment/e.conversion_rate as amount
					from ld_sendcashbill e
					inner JOIN (select * from (
							select sendcashbillid,entitytypeid 
								from ld_sendcashbill2payment 
								order by sendcashbillid,sequence) t group by sendcashbillid) f on e.sendcashbillid=f.sendcashbillid
							where e.deleted=0 and e.nosendpayment<>0 and f.entitytypeid>0 
								and IF(e.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)) as g) as h
				LEFT JOIN ld_sendpayment i on h.entitytypeid=i.sendpaymentid
				where i.Purchaseorder_id=@tmp_entitytypeid
				group by i.Purchaseorder_id;

			select
				max(a.cashbilldate) into @purs_date2
			from ld_sendcashbill a 
			INNER JOIN ld_sendcashbill2payment b on a.sendcashbillid=b.sendcashbillid
			LEFT JOIN ld_sendpayment c on b.entitytypeid=c.sendpaymentid
			where a.deleted=0 and c.purchaseorder_id=@tmp_entitytypeid
				and IF(a.checkoutstatus='已审核',1,0) <> IF(@deploy_value=1,0,0.001)
			group by c.Purchaseorder_id;
			
			IF tmp_entitytype='PurchaseOrder' THEN
				update ld_purchaseorder set pay_amount=round(@purs_total*conversion_rate,2)+round(@purs_total2*conversion_rate,2),pay_balance=round(total-pay_amount,2),sendcashbilldate=IF(@purs_date>@purs_date2,@purs_date,@purs_date2) where purchaseorderid=@tmp_entitytypeid;
			ELSEIF tmp_entitytype='PurchaseInvoice' THEN
				update ld_purchaseinvoice set pay_amount=round(@purs_total*conversion_rate,2),pay_balance=round(total-round(@purs_total*conversion_rate,2),2),sendcashbilldate=@purs_date where purchaseinvoiceid=@tmp_entitytypeid;			
