-- ----------------------------
-- Event structure for update_account_nolinkdays
-- ----------------------------
DROP EVENT IF EXISTS `update_account_nolinkdays`;
DELIMITER ;;
CREATE EVENT `update_account_nolinkdays` ON SCHEDULE EVERY 1 DAY STARTS '2016-05-24 00:30:00' ON COMPLETION NOT PRESERVE ENABLE DO update ld_account set nolinkdays=datediff(CURDATE(),ifnull(lastcontactdate,date_format(createdtime,'%Y-%m-%d')))
;;
DELIMITER ;

-- ----------------------------
-- Event structure for update_potential_staydays
-- ----------------------------
DROP EVENT IF EXISTS `update_potential_staydays`;
DELIMITER ;;
CREATE EVENT `update_potential_staydays` ON SCHEDULE EVERY 1 DAY STARTS '2016-09-01 00:30:00' ON COMPLETION NOT PRESERVE ENABLE DO update 
ld_potential a
LEFT JOIN (
	select 
		potentialid,max(lastmodified) as lastmodified
	from ld_potstagehistory 
	where stage<>sales_stage 
	GROUP BY potentialid) b on a.potentialid=b.potentialid
set a.staydays=datediff(NOW(),ifnull(b.lastmodified,a.createdtime))
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `up_account_nolinkdays`;
DELIMITER ;;
CREATE TRIGGER `up_account_nolinkdays` BEFORE UPDATE ON `ld_account` FOR EACH ROW BEGIN 

	IF ifnull(new.lastcontactdate,'0000-00-00')<>ifnull(old.lastcontactdate,'0000-00-00') THEN
		SET new.nolinkdays=datediff(CURDATE(),ifnull(new.lastcontactdate,date_format(new.createdtime,'%Y-%m-%d')));
	END IF;

END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `ldcrm_updatesykq_byaddjobbill`;
DELIMITER ;;
CREATE TRIGGER `ldcrm_updatesykq_byaddjobbill` AFTER UPDATE ON `ld_addjobbill` FOR EACH ROW BEGIN 

	IF (new.approvestatus='已批准' and old.approvestatus<>'已批准') OR (new.approvestatus<>'已批准' and old.approvestatus='已批准') THEN
		CALL ldcrm_update_sykq_byuserid(new.smownerid);
	END IF;

	IF new.smownerid<>old.smownerid THEN
		CALL ldcrm_update_sykq_byuserid(new.smownerid);
		CALL ldcrm_update_sykq_byuserid(old.smownerid);
	END IF;
	
END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `ldcrm_insertsykq_byaddjobbill`;
DELIMITER ;;
CREATE TRIGGER `ldcrm_insertsykq_byaddjobbill` BEFORE INSERT ON `ld_addjobbillscf` FOR EACH ROW BEGIN 


	SET @total_sy_tx=0;
	SET @total_sy_nj=0;
	
	SELECT
		total_sy_tx into @total_sy_tx
	FROM (
		SELECT
			a.id, 
			a.last_name,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t
	WHERE id=(SELECT smownerid FROM ld_addjobbill WHERE addjobbillid=NEW.addjobbillid) LIMIT 1;
	
	SELECT
		concat(t.total_sy_nj,IFNULL(CONCAT('(',t.this_njstart,')'),'')) into @total_sy_nj
	FROM (
		SELECT
			a.id, 
			a.last_name,
            a.this_njstart,
			IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='加班' AND approvestatus='已批准'),0)
				-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='调休' AND approvestatus='已批准'),0) AS total_sy_tx,
			CASE
				WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN
					0-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准'),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)>CURDATE() THEN
					0
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 1 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)>CURDATE() THEN
					5*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 10 YEAR)<=CURDATE() AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)>CURDATE() THEN
					10*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				WHEN a.hire_date>'1990-01-01' AND DATE_ADD(a.hire_date,INTERVAL 20 YEAR)<=CURDATE() THEN
					15*8-IFNULL((SELECT SUM(costtime) FROM vw_oa_attendance WHERE smownerid=a.id AND timetype='年假' AND approvestatus='已批准' AND workdate>=a.this_njstart AND workdate<DATE_ADD(a.this_njstart,INTERVAL 1 YEAR)),0)
				ELSE 112
			END AS total_sy_nj
		FROM (
			SELECT
					a.id,
					a.last_name,
					a.`status`,
					a.hire_date,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						WHEN DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)<=CURDATE() THEN
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date) YEAR)
						ELSE
							DATE_ADD(a.hire_date,INTERVAL YEAR(CURDATE())-YEAR(a.hire_date)-1 YEAR)
					END AS this_njstart,
					CASE
						WHEN LENGTH(IFNULL(a.hire_date,''))<1 OR a.hire_date='0000-00-00' THEN NULL
						ELSE
							DATE_ADD(a.hire_date,INTERVAL 2017-YEAR(a.hire_date) YEAR)
					END AS extra_njend
				FROM ld_users a
		) a
	) t
	WHERE id=(SELECT smownerid FROM ld_addjobbill WHERE addjobbillid=NEW.addjobbillid) LIMIT 1;

	SET NEW.sytx=@total_sy_tx;
	SET NEW.synj=@total_sy_nj;	
	
END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `update_salesorder_received1`;
DELIMITER ;;
CREATE TRIGGER `update_salesorder_received1` AFTER UPDATE ON `ld_cashbill` FOR EACH ROW BEGIN 
 
 call update_sales_total(new.cashbillid);
		
END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `update_salesorder_received3`;
DELIMITER ;;
CREATE TRIGGER `update_salesorder_received3` AFTER DELETE ON `ld_cashbill2paymentplan` FOR EACH ROW BEGIN 
    IF old.entitytypeid>0 and length(ifnull(old.entitytype,''))>1 THEN
	   call update_sales_total2(old.entitytypeid,old.entitytype);
    END IF;

	IF old.entitytype='PaymentPlan' THEN
		set @id=0;
		set @module=NULL;
		select entitytypeid into @id from ld_paymentplan where paymentplanid=old.entitytypeid;
		select entitytype into @module from ld_paymentplan where paymentplanid=old.entitytypeid;
		IF @id>0 THEN
			call update_sales_total2(@id,@module);
		END IF;

	END IF;
		
END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `update_account_firtconcatuser1`;
DELIMITER ;;
CREATE TRIGGER `update_account_firtconcatuser1` AFTER INSERT ON `ld_contactrecords` FOR EACH ROW BEGIN 

		set @cnt=0;
		select count(1) into @cnt from ld_contactrecords where accountid=new.accountid and deleted=0;
		
		IF @cnt=1 and new.accountid>0 THEN
				update ld_account set firt_concatuser=new.smownerid where accountid=new.accountid;
		END IF;

END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `update_by_invoice1`;
DELIMITER ;;
CREATE TRIGGER `update_by_invoice1` BEFORE UPDATE ON `ld_invoice` FOR EACH ROW BEGIN 

	set new.receivable_balance=round(ifnull(new.total,0)-ifnull(new.received_amount,0),2);
	
END
;;
DELIMITER ;
DROP TRIGGER IF EXISTS `update_account_lastservicedate`;
DELIMITER ;;
CREATE TRIGGER `update_account_lastservicedate` AFTER INSERT ON `ld_maxservicedate` FOR EACH ROW BEGIN 

IF NEW.accountid>0 THEN
	update ld_account set lastservicedate=(SELECT max(service_enddate) from ld_maxservicedate where accountid=NEW.accountid) where accountid=NEW.accountid;
END IF;

END
;;
DELIMITER ;
