INSERT INTO `ld_autotaskquery` VALUES ('1', 'DROP PROCEDURE IF EXISTS `task_turntopublick_over30days`;\r\ndelimiter $$\r\nCREATE  PROCEDURE `task_turntopublick_over30days`(\r\n)\r\nBEGIN\r\n	declare tmp_accountid  int default 0;\r\n	declare tmp_accountname varchar(200) default \'\';\r\n	declare tmp_smownerid  int default 0;\r\n	declare mycursor cursor for select accountid, accountname,smownerid from ld_account where nolinkdays>30 and publicaccount<>1;\r\n	DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n	open mycursor;\r\n	fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid;\r\n	while(tmp_accountid is not null) DO\r\n		update ld_account set protectdate=NULL,publicaccount=1 where accountid=tmp_accountid;\r\n		set @maxid=0;\r\n		select max(crmid) into @maxid from ld_crmentity;\r\n		insert into ld_crmentity(crmid,setype)\r\n		select @maxid+1,\'Reminds\';\r\n\r\n		update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n\r\n		insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n		select @maxid+1,concat(\'计划任务：30天未联系客户自动转公海已执行，客户：\',tmp_accountname,\'已自动转公海！\'),now(),tmp_smownerid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n		\r\n\r\n		INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,Labeltype)\r\n		SELECT \'zh\',\'TASK_30DAYNOLINK_TOBETHEHIGHSEAS\',\'自动任务：30天未联系客户自动转公海\',\'fixedstr\' FROM DUAL \r\n		WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE labelbol=\'TASK_30DAYNOLINK_TOBETHEHIGHSEAS\' AND languagetype=\'zh\');\r\n\r\n		INSERT INTO ld_desk(languagetype,labelbol,fieldlabel,Labeltype)\r\n		SELECT \'en\',\'TASK_30DAYNOLINK_TOBETHEHIGHSEAS\',\'自动任务：30天未联系客户自动转公海\',\'fixedstr\' FROM DUAL \r\n		WHERE NOT EXISTS (SELECT 1 FROM ld_desk WHERE labelbol=\'TASK_30DAYNOLINK_TOBETHEHIGHSEAS\' AND languagetype=\'en\');\r\n	\r\n		insert into ld_logpublicaccount(username,operation,opdate,accountid)\r\n		select \'系统\',\'TASK_30DAYNOLINK_TOBETHEHIGHSEAS\',NOW(),tmp_accountid;\r\n\r\n		fetch mycursor into tmp_accountid,tmp_accountname,tmp_smownerid;\r\n\r\n	end while;\r\n	close mycursor;\r\nEND $$\r\ndelimiter;\r\ncall task_turntopublick_over30days;\r\ndelimiter;');
INSERT INTO `ld_autotaskquery` VALUES ('2', 'DROP PROCEDURE IF EXISTS `task_contact_birthday_reminds_before1day`; \r\ndelimiter $$ \r\nCREATE PROCEDURE `task_contact_birthday_reminds_before1day`( \r\n) \r\nBEGIN \r\nDECLARE done int DEFAULT 0; \r\nDECLARE task_crmid int default 0; \r\nDECLARE task_name varchar(200) default \'\'; \r\nDECLARE task_user int default 0; \r\nDECLARE task_time datetime DEFAULT NOW(); \r\nDECLARE mycursor cursor for SELECT contactid,lastname,smownerid FROM ld_contactdetails WHERE deleted = 0 AND birthday != \'\' AND \r\n(DATE_FORMAT(birthday,\'%m%d\') - DATE_FORMAT(CURDATE(),\'%m%d\') = 1) ORDER BY contactid; \r\nDECLARE CONTINUE HANDLER for not found set dOne= 1; \r\nOPEN mycursor; \r\nfetch mycursor into task_crmid,task_name,task_user; \r\nLOOP1: WHILE done != 1 DO \r\nIF task_crmid > 0 THEN \r\nset @maxid = 0; \r\nselect max(crmid) into @maxid from ld_crmentity; \r\ninsert into ld_crmentity(crmid,setype) \r\nselect @maxid+1,\'Reminds\'; \r\ninsert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted) \r\nselect @maxid+1,concat(\'明天是\',task_name,\'的生日，请送上生日的祝福。\'),task_time,task_user,\'未读\',task_crmid,\'Contacts\',0,0,0,1,1,1,task_time,task_time,\'\',0; \r\nupdate ld_crmentity_seq set id=(select max(crmid) from ld_crmentity); \r\nEND IF; \r\nFETCH mycursor INTO task_crmid,task_name,task_user; \r\nEND WHILE LOOP1; \r\nclose mycursor; \r\nEND $$\r\ndelimiter;\r\nCALL task_contact_birthday_reminds_before1day();\r\ndelimiter;');
INSERT INTO `ld_autotaskquery` VALUES ('3', 'DROP PROCEDURE IF EXISTS `task_accounts_remind_lastservicedate`;\r\ndelimiter ||\r\nCREATE PROCEDURE `task_accounts_remind_lastservicedate`(\r\n)\r\nBEGIN\r\n	\r\n\r\n	declare tmp_accountid int(19) default 0;\r\n	declare tmp_accountname varchar(255) default NULL;\r\n	declare tmp_date date default NULL;\r\n	declare tmp_recieverid int(19) default 0;\r\n	declare tmp_days int(19) default 0;\r\n\r\n	declare cur1 cursor for SELECT \r\n								accountid,\r\n								accountname,\r\n								lastservicedate,\r\n								smownerid,\r\n								DATEDIFF(lastservicedate,CURDATE()) AS days\r\n							FROM ld_account\r\n							WHERE deleted=0\r\n								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);\r\n\r\n	DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n\r\n	OPEN cur1;\r\n	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\r\n	while(tmp_accountid is not null) DO\r\n		IF tmp_days<=-30 THEN\r\n			SET @remind_type=\'自动任务之服务过期提醒\';\r\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'Accounts\' and content like \'自动任务之服务过期提醒%\') THEN\r\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务已经过期\',abs(tmp_days),\'天（\',tmp_date,\'），请及时跟进！\');\r\n\r\n				set @maxid=0;\r\n				select max(crmid) into @maxid from ld_crmentity;\r\n				insert into ld_crmentity(crmid,setype)\r\n				select @maxid+1,\'Reminds\';			\r\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n			\r\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n			END IF;\r\n		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN\r\n			SET @remind_type=\'自动任务之服务到期提醒\';\r\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'Accounts\' and content like \'自动任务之服务到期提醒%\') THEN\r\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务已经到期（\',tmp_date,\'），请及时跟进！\');\r\n\r\n				set @maxid=0;\r\n				select max(crmid) into @maxid from ld_crmentity;\r\n				insert into ld_crmentity(crmid,setype)\r\n				select @maxid+1,\'Reminds\';			\r\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n			\r\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n			END IF;\r\n		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN\r\n			SET @remind_type=\'自动任务之服务即将到期提醒\';\r\n			\r\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'Accounts\' and content like \'自动任务之服务即将到期提醒%\') THEN\r\n				\r\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'还有\',abs(tmp_days),\'天（\',tmp_date,\'）即将到期，请及时跟进！\');\r\n				set @maxid=0;\r\n				select max(crmid) into @maxid from ld_crmentity;\r\n				insert into ld_crmentity(crmid,setype)\r\n				select @maxid+1,\'Reminds\';			\r\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'Accounts\',0,0,0,1,1,1,now(),now(),null,0;\r\n			\r\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n			END IF;\r\n		END IF;\r\n		\r\n		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\r\n	end while;\r\n	close cur1;\r\n\r\n\r\nend ||\r\ndelimiter;\r\n\r\nCALL task_accounts_remind_lastservicedate();\r\ndelimiter;');
INSERT INTO `ld_autotaskquery` VALUES ('4', 'DROP PROCEDURE IF EXISTS `task_servicecharge_remind_lastservicedate`;\r\ndelimiter ||\r\nCREATE PROCEDURE `task_servicecharge_remind_lastservicedate`(\r\n)\r\nBEGIN\r\n	\r\n\r\n	declare tmp_accountid int(19) default 0;\r\n	declare tmp_accountname varchar(255) default NULL;\r\n	declare tmp_date date default NULL;\r\n	declare tmp_recieverid int(19) default 0;\r\n	declare tmp_days int(19) default 0;\r\n\r\n	declare cur1 cursor for SELECT \r\n								accountid,\r\n								accountname,\r\n								lastservicedate,\r\n								CASE WHEN servicecasher>0 THEN servicecasher ELSE 1 END AS servicecasher,\r\n								DATEDIFF(lastservicedate,CURDATE()) AS days\r\n							FROM ld_account\r\n							WHERE deleted=0\r\n								AND lastservicedate BETWEEN DATE_SUB(CURDATE(),INTERVAL 37 DAY) AND DATE_ADD(CURDATE(),INTERVAL 30 DAY);\r\n\r\n	DECLARE CONTINUE HANDLER FOR SQLSTATE \'02000\' set tmp_accountid = NULL;\r\n\r\n	OPEN cur1;\r\n	Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\r\n	while(tmp_accountid is not null) DO\r\n		IF tmp_days<=-30 THEN\r\n			SET @remind_type=\'自动任务之服务过期提醒\';\r\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'ServiceCharge\' and content like \'自动任务之服务过期提醒%\') THEN\r\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务已经过期\',abs(tmp_days),\'天（\',tmp_date,\'），请及时跟进！\');\r\n\r\n				set @maxid=0;\r\n				select max(crmid) into @maxid from ld_crmentity;\r\n				insert into ld_crmentity(crmid,setype)\r\n				select @maxid+1,\'Reminds\';			\r\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'ServiceCharge\',0,0,0,1,1,1,now(),now(),null,0;\r\n			\r\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n			END IF;\r\n		ELSEIF tmp_days=0 AND tmp_days>=-7 THEN\r\n			SET @remind_type=\'自动任务之服务到期提醒\';\r\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'ServiceCharge\' and content like \'自动任务之服务到期提醒%\') THEN\r\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'服务已经到期（\',tmp_date,\'），请及时跟进！\');\r\n\r\n				set @maxid=0;\r\n				select max(crmid) into @maxid from ld_crmentity;\r\n				insert into ld_crmentity(crmid,setype)\r\n				select @maxid+1,\'Reminds\';			\r\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'ServiceCharge\',0,0,0,1,1,1,now(),now(),null,0;\r\n			\r\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n			END IF;\r\n		ELSEIF tmp_days>=23 AND tmp_days<=30 THEN\r\n			SET @remind_type=\'自动任务之服务即将到期提醒\';\r\n			\r\n			IF not exists (select 1 from ld_reminds where related_to=tmp_accountid and reltab=\'ServiceCharge\' and content like \'自动任务之服务即将到期提醒%\') THEN\r\n				\r\n				set @content=concat(@remind_type,\'，您的客户\',tmp_accountname,\'还有\',abs(tmp_days),\'天（\',tmp_date,\'）即将到期，请及时跟进！\');\r\n				set @maxid=0;\r\n				select max(crmid) into @maxid from ld_crmentity;\r\n				insert into ld_crmentity(crmid,setype)\r\n				select @maxid+1,\'Reminds\';			\r\n				insert into ld_reminds(remindsid,content,date_time,recieverid,status_rmd,related_to,reltab,is_del_send,is_del_rec,reminds_ruleid,smownerid,smcreatorid,modifiedby,createdtime,modifiedtime,description,deleted)\r\n				select @maxid+1,@content,now(),tmp_recieverid,\'未读\',tmp_accountid,\'ServiceCharge\',0,0,0,1,1,1,now(),now(),null,0;\r\n			\r\n				update ld_crmentity_seq set id=(select max(crmid) from ld_crmentity);\r\n			END IF;\r\n		END IF;\r\n		\r\n		Fetch cur1 into tmp_accountid,tmp_accountname,tmp_date,tmp_recieverid,tmp_days;\r\n	end while;\r\n	close cur1;\r\n\r\n\r\nend ||\r\ndelimiter;\r\n\r\nCALL task_servicecharge_remind_lastservicedate();\r\ndelimiter;');
