INSERT INTO `ld_desk` VALUES ('11988', 'zh', 'PMWARMREMINDFORPASSWORD', '密码规范$=$\r\n            1.普通用户每隔90天需要重置密码，管理员用户每隔30天需要重置密码;$=$\r\n            2.普通用户密码至少需要8位，管理员至少需要15位;$=$\r\n            3.密码不能包含用户账户或者用户名信息;\r\n             ', 'fixedstr');
INSERT INTO `ld_desk` VALUES ('11989', 'zh', 'PMWARMREMINDFORPASSWORDADD', '4.密码至少需要符合以下3项要求：$=$\r\n            包含大写英文字母(A-Z)$=$\r\n            包含小写英文字母(a-z)$=$\r\n            包含数字(0-9)$=$\r\n            包含特殊字符(!@#$...)', 'fixedstr');
INSERT INTO `ld_desk` VALUES ('11990', 'en', 'PMWARMREMINDFORPASSWORD', 'Password Specification$=$1.General users need to reset the password every 90 days, administrator users need to reset the password every 30 days;$=$2.General users\'password should contain at least 8 digits, the administrator users\'password should contain at least 15 digits;$=$3.Password cannot contain the users\' account or users\' name;', 'fixedstr');
INSERT INTO `ld_desk` VALUES ('11991', 'en', 'PMWARMREMINDFORPASSWORDADD', '4.Password meets at least the following 3 requirements:$=$  Contains capital letters$=$  Contains small letters$=$  Contains numbers$=$  Contains special characters', 'fixedstr');
