INSERT INTO `ld_field` VALUES ('29', '510', 'currency_grouping_pattern', 'yes', 'ld_users', '1', '16', 'currency_grouping_pattern', 'Digit Grouping Pattern', '1', '0', null, '100', '2', '78', '1', 'V~O', '1', null, 'BAS', '1', '<b>Currency - Digit Grouping Pattern</b> <br/><br/>This pattern specifies the format in which the currency separator will be placed.', '0', '0', '1', '1', '0', '0', null, null, '2', '0', 'yes', 'yes', 'yes', 'yes', 'yes');
INSERT INTO `ld_field` VALUES ('29', '511', 'currency_decimal_separator', 'yes', 'ld_users', '1', '16', 'currency_decimal_separator', 'Decimal Separator', '1', '0', null, '2', '3', '78', '1', 'V~O', '1', null, 'BAS', '1', '<b>Currency - Decimal Separator</b> <br/><br/>Decimal separator specifies the separator to be used to separate the fractional values from the whole number part. <br/><b>Eg:</b> <br/>. => 123.45 <br/>, => 123,45 <br/>\' => 123\'45 <br/>  => 123 45 <br/>$ => 123$45 <br/>', '0', '0', '1', '1', '0', '0', null, null, '2', '0', 'yes', 'yes', 'yes', 'yes', 'yes');
