INSERT INTO `ld_field` VALUES ('29', '513', 'currency_symbol_placement', 'yes', 'ld_users', '1', '16', 'currency_symbol_placement', 'Symbol Placement', '1', '0', null, '20', '5', '78', '1', 'V~O', '1', null, 'BAS', '1', '<b>Currency - Symbol Placement</b> <br/><br/>Symbol Placement allows you to configure the position of the currency symbol with respect to the currency value.<br/><b>Eg:</b> <br/>$1.0 => $123,456,789.50 <br/>1.0$ => 123,456,789.50$ <br/>', '0', '0', '1', '1', '0', '0', null, null, '2', '0', 'yes', 'yes', 'yes', 'yes', 'yes');
