INSERT INTO `ld_related_field` VALUES ('150', null, 'main', null, '2201', '2202', '', 'sql', 'select CONCAT(ld_account.bill_city,ld_account.bill_street) as address from ld_account where ld_account.deleted = 0 and accountid = ? UNION select CONCAT(ld_account.bill_city,ld_account.bill_street) as address from ld_contactdetails INNER JOIN ld_account on ld_account.accountid = ld_contactdetails.accountid where ld_account.deleted = 0 and ld_contactdetails.contactid = ? UNION select CONCAT(ld_account.bill_city,ld_account.bill_street) as address from ld_contactrecords INNER JOIN ld_account on ld_account.accountid = ld_contactrecords.accountid where ld_account.deleted = 0 and ld_contactrecords.contactrecordID = ? UNION select CONCAT(ld_account.bill_city,ld_account.bill_street) as address from ld_potential INNER JOIN ld_account on ld_account.accountid = ld_potential.accountid where ld_account.deleted = 0 and ld_potential.potentialid = ? UNION select CONCAT(ld_account.bill_city,ld_account.bill_street) as address from ld_project INNER JOIN ld_account on ld_account.accountid = ld_project.accountid where ld_account.deleted = 0 and ld_project.projectid = ?');
